import type {Escape} from './types.js';
import type {CoverageRow,CoverageValue} from './results.js';
import {relationLabel} from './spatial-coverage.js';
export function coverageTable(output:CoverageValue,esc:Escape){return {head:'<th>Record / layer</th><th>Spatial relation</th><th>Action</th>',body:output.rows.map(r=>`<tr tabindex="0" data-place="${esc(r.id)}"><td>${esc(r.name)}<br><small>${esc(r.layerLabel||'')}</small></td><td>${esc(relationLabel(r.relation))}</td><td>${r.excluded?'Excluded · '+esc(r.exclusionReason):r.decision==='Review'?'Review required':'Included'}</td></tr>`).join('')};}
export function coverageEvidence(output:CoverageValue,row:CoverageRow,dirty:boolean,esc:Escape){
  return `<div class="inspector-body"><span class="inspector-section">Spatial coverage ${dirty?'· previous run':''}</span><h2>${esc(row.name)}</h2><p class="muted">${esc(row.layerLabel)} · record ${esc(row.recordId)}</p><div class="source-card"><h3>${esc(relationLabel(row.relation))}</h3><p>${row.coordinates?row.coordinates.map(v=>v.toFixed(6)).join(', '):'No coordinate supplied'}</p></div><p class="description">Outside the study boundary is a scope mismatch, not proof of a data-quality error. Boundary points are included.</p>${row.excluded?`<p class="notice">Excluded from this check's retained dataset: ${esc(row.exclusionReason)}</p><button id="coverage-restore" class="button small" ${dirty?'disabled':''}>Restore record</button>`:`<form id="coverage-exclude-form" class="field"><label class="field-label" for="exclusion-reason">Reason for data-quality exclusion</label><input id="exclusion-reason" required maxlength="300" placeholder="Describe the verified problem" ${dirty?'disabled':''}><button type="submit" class="button small" ${dirty?'disabled':''}>Exclude as data-quality issue</button></form>`}${row.coordinates?`<button id="coverage-edit-boundary" class="button primary" ${dirty?'disabled':''}>Edit study boundary with this point</button>`:''}<p class="muted">${dirty?'Rerun before making decisions from these results.':'Original input records are preserved. After changing an exclusion or the boundary, rerun the check.'}</p>${output.pointTable?`<div class="inspector-divider"></div><span class="inspector-section">Point attributes</span>${Object.entries(row.attributes).map(([key,value])=>`<div class="detail-row"><span>${esc(key)}</span><strong>${esc(value===null?'Not supplied':value)}</strong></div>`).join('')}`:''}</div>`;
}
